// The eight gym badges (STORY_BIBLE §5). Saved as flags `badge_<id>`. Each unlocks one
// field skill (systems/skills.ts). Icons: ui/badge_<id> (16×16, case) and ui/badge_<id>_big
// (32×32, badge-get scene), generated by tools/ui/badges.py; procedural fallback in code.

import { state } from '../state'

export interface BadgeDef {
  id: string
  name: string
  gym: number
  leader: string
  town: string
  /** Field skill this badge unlocks. */
  skill: string
  /** Two-tone colour for the procedural fallback icon. */
  colors: [number, number, number]
}

export const BADGES: BadgeDef[] = [
  { id: 'gradient', name: 'Gradient Badge', gym: 1, leader: 'Rumelhart', town: 'SoMa Node', skill: 'backprop', colors: [0x8c2c34, 0xe06c5c, 0xf8d838] },
  { id: 'likelihood', name: 'Likelihood Badge', gym: 2, leader: 'Shannon', town: 'Menlo Park', skill: 'sample', colors: [0x2c4a8c, 0x5c94e0, 0xd8f0fc] },
  { id: 'embedding', name: 'Embedding Badge', gym: 3, leader: 'Bengio', town: 'Palo Alto', skill: 'embed', colors: [0x1c6440, 0x58c478, 0xa4e27a] },
  { id: 'normal', name: 'Normal Badge', gym: 4, leader: 'Ioffe', town: 'Mountain View', skill: 'normalize', colors: [0x1c6a6c, 0x48bcae, 0xb4e0f8] },
  { id: 'chain', name: 'Chain Badge', gym: 5, leader: 'Hinton', town: 'Toronto', skill: 'chain', colors: [0x4a5262, 0xa8b4c0, 0xf4f6fa] },
  { id: 'wave', name: 'Wave Badge', gym: 6, leader: 'van den Oord', town: 'Waterloo', skill: 'dilate', colors: [0x48308c, 0xa084e8, 0xfce070] },
  { id: 'attention', name: 'Attention Badge', gym: 7, leader: 'Vaswani', town: 'Seattle', skill: 'attend', colors: [0xa84818, 0xf07830, 0xfcb060] },
  { id: 'merge', name: 'Merge Badge', gym: 8, leader: 'Sennrich', town: 'Redmond', skill: 'merge', colors: [0xa83c6c, 0xe06c98, 0xf8a8c4] },
]

export function badgeDef(id: string): BadgeDef | undefined {
  return BADGES.find((b) => b.id === id)
}

export function badgeFlag(id: string): string {
  return `badge_${id}`
}

export function hasBadge(id: string): boolean {
  return state.flag(badgeFlag(id))
}

export function badgeCount(): number {
  return BADGES.filter((b) => hasBadge(b.id)).length
}

/** Rename / re-colour a badge (CONTENT), e.g. registerBadge({ ...badgeDef('gradient')!, name: 'Gradient Badge' }). */
export function registerBadge(b: BadgeDef): void {
  const i = BADGES.findIndex((x) => x.id === b.id)
  if (i >= 0) BADGES[i] = b
  else BADGES.push(b)
}
